files.api/routes/invoices.py:
from fastapi import APIRouter
router = APIRouter()

@router.get('/invoices/{id}/pdf')
def invoice_pdf(id: str):
    return render(id)

files.api/static/js/invoices.js:
export async function download(id) {
  const r = await fetch(`/invoices/${id}/pdf`);
  return r.blob();
}

call.content:
openapi: 3.0.3
info:
  title: Invoice export
  version: 1.0.0
paths:
  /invoices/{id}/exports:
    post:
      summary: Start an export of one invoice
      responses:
        '202': {description: Export}
        '400': {description: bad_format}
        '403': {description: not_owner}
        '404': {description: no_invoice}
        '409': {description: already_running}
  /exports/{export_id}:
    get:
      summary: The export's state and file link
      responses:
        '200': {description: Export}
        '403': {description: not_owner}
        '404': {description: no_export}
components:
  schemas:
    ExportRequest:
      type: object
      required: [format]
      properties:
        format: {type: string, enum: [pdf, csv]}
    Export:
      type: object
      properties:
        id: {type: string}
        status: {type: string, enum: [queued, ready, failed]}
        url: {type: string}

